package ru.main.explorer;
import android.graphics.*;import java.io.*;import java.util.*;import java.util.zip.*;

/** Bounded reader for the published Mapbox Vector Tile protobuf wire format. */
final class Mvt {
 static final class Tile {final ArrayList<Feature> features=new ArrayList<>();final HashMap<Long,ArrayList<Feature>> buildings=new HashMap<>();final ArrayList<Feature> largeBuildings=new ArrayList<>();int vertices,references;int bytes(){return Math.max(1,vertices*24+features.size()*256+references*16);}static long key(int x,int y){return ((long)x<<32)^(y&0xffffffffL);}void index(){for(Feature f:features){if(f.type!=3||!WorldMap.isBuilding(f.layer))continue;int left=(int)Math.floor(f.bounds.left/f.extent*16),right=(int)Math.floor(f.bounds.right/f.extent*16),top=(int)Math.floor(f.bounds.top/f.extent*16),bottom=(int)Math.floor(f.bounds.bottom/f.extent*16);if((long)(right-left+1)*(bottom-top+1)>64){largeBuildings.add(f);references++;continue;}for(int x=left;x<=right;x++)for(int y=top;y<=bottom;y++){buildings.computeIfAbsent(key(x,y),k->new ArrayList<>()).add(f);references++;}}}Collection<Feature> nearBuildings(double left,double top,double right,double bottom){HashSet<Feature> result=new HashSet<>(largeBuildings);for(int x=(int)Math.floor(left*16);x<=(int)Math.floor(right*16);x++)for(int y=(int)Math.floor(top*16);y<=(int)Math.floor(bottom*16);y++){ArrayList<Feature> bucket=buildings.get(key(x,y));if(bucket!=null)result.addAll(bucket);}return result;}}
 static final class Feature {String layer,name="",kind="";int type,extent;final ArrayList<float[]> parts=new ArrayList<>();final Path path=new Path();final RectF bounds=new RectF();}
 static final class Reader {final byte[] data;int at;final int end;Reader(byte[] data){this(data,0,data.length);}Reader(byte[] data,int start,int end){this.data=data;at=start;this.end=end;}boolean more(){return at<end;}long number()throws IOException{long value=0;for(int shift=0;shift<70;shift+=7){if(at>=end)throw new EOFException(Messages.text("truncated_vector_tile"));int b=data[at++]&255;if(shift==63&&(b&254)!=0)throw new IOException(Messages.text("mvt_number_too_long"));value|=(long)(b&127)<<shift;if((b&128)==0)return value;}throw new IOException(Messages.text("invalid_mvt"));}int length()throws IOException{long n=number();if(n<0||n>end-at)throw new IOException(Messages.text("invalid_mvt_length"));return (int)n;}Reader message()throws IOException{int n=length();Reader child=new Reader(data,at,at+n);at+=n;return child;}String string()throws IOException{Reader child=message();if(child.end-child.at>65536)throw new IOException(Messages.text("label_too_long"));return new String(data,child.at,child.end-child.at,"UTF-8");}void skip(int wire)throws IOException{if(wire==0)number();else if(wire==1)advance(8);else if(wire==2)advance(length());else if(wire==5)advance(4);else throw new IOException(Messages.text("unknown_mvt_field"));}void advance(int n)throws IOException{if(n<0||n>end-at)throw new EOFException();at+=n;}}
 static Tile decode(byte[] bytes)throws IOException{if(bytes==null||bytes.length==0||bytes.length>8*1024*1024)throw new IOException(Messages.text("invalid_tile_size"));if(bytes.length>2&&(bytes[0]&255)==31&&(bytes[1]&255)==139){try(InputStream in=new GZIPInputStream(new ByteArrayInputStream(bytes));ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[16384];int n;while((n=in.read(b))!=-1){out.write(b,0,n);if(out.size()>16*1024*1024)throw new IOException(Messages.text("vector_tile_too_large"));}bytes=out.toByteArray();}}Tile tile=new Tile();Reader reader=new Reader(bytes);int layers=0;while(reader.more()){int tag=(int)reader.number();if(tag==26){if(++layers>128)throw new IOException(Messages.text("too_many_layers"));layer(reader.message(),tile);}else reader.skip(tag&7);}if(layers==0)throw new IOException(Messages.text("mbtiles_with_mvt_pbf_is_required_rather_than_raw_osm_pbf"));tile.index();return tile;}
 static void layer(Reader r,Tile tile)throws IOException{String name="";int extent=4096,version=1;ArrayList<String> keys=new ArrayList<>();ArrayList<String> values=new ArrayList<>();ArrayList<Reader> features=new ArrayList<>();while(r.more()){int tag=(int)r.number();switch(tag){case 10:name=r.string();break;case 18:if(features.size()>=50000)throw new IOException(Messages.text("too_many_features"));features.add(r.message());break;case 26:keys.add(r.string());break;case 34:values.add(value(r.message()));break;case 40:extent=(int)r.number();break;case 120:version=(int)r.number();break;default:r.skip(tag&7);}}if(extent<1||extent>65536||version<1||version>2)throw new IOException(Messages.text("unsupported_mvt_version"));for(Reader feature:features){Feature f=feature(feature,name,extent,keys,values,tile);if(!f.parts.isEmpty())tile.features.add(f);}}
 static String value(Reader r)throws IOException{String result="";while(r.more()){int tag=(int)r.number();if(tag==10)result=r.string();else if(tag==32||tag==40||tag==56)result=Long.toString(r.number());else if(tag==48){long n=r.number();result=Long.toString((n>>>1)^-(n&1));}else r.skip(tag&7);}return result;}
 static Feature feature(Reader r,String layer,int extent,List<String> keys,List<String> values,Tile tile)throws IOException{Feature f=new Feature();f.layer=layer;f.extent=extent;ArrayList<Integer> tags=new ArrayList<>();ArrayList<Reader> commands=new ArrayList<>();while(r.more()){int tag=(int)r.number();if(tag==18){Reader packed=r.message();while(packed.more()){if(tags.size()>1024)throw new IOException(Messages.text("too_many_attributes"));tags.add((int)packed.number());}}else if(tag==24)f.type=(int)r.number();else if(tag==34)commands.add(r.message());else r.skip(tag&7);}if(tags.size()%2!=0)throw new IOException(Messages.text("invalid_attributes"));String fallback="",russian="";for(int i=0;i<tags.size();i+=2){int k=tags.get(i),v=tags.get(i+1);if(k<0||v<0||k>=keys.size()||v>=values.size())throw new IOException(Messages.text("invalid_dictionary"));String key=keys.get(k),text=values.get(v);if(key.equals("name"))f.name=text;if(key.equals("name:ru")||key.equals("name_ru"))russian=text;if(key.equals("name:latin")||key.equals("ref")||key.equals("housenumber"))fallback=text;if(key.equals("class")||key.equals("kind"))f.kind=text;}if(!russian.isEmpty())f.name=russian;else if(f.name.isEmpty())f.name=fallback;if(f.type<1||f.type>3)return f;
  int x=0,y=0;ArrayList<Float> part=null;for(Reader geometry:commands)while(geometry.more()){long encoded=geometry.number();int command=(int)(encoded&7),count=(int)(encoded>>>3);if(count<1||count>400000)throw new IOException(Messages.text("invalid_geometry_commands"));if(command==7){if(count!=1||part==null||f.type!=3)throw new IOException(Messages.text("invalid_polygon_closure"));continue;}if(command!=1&&command!=2)throw new IOException(Messages.text("unknown_geometry"));for(int i=0;i<count;i++){long a=geometry.number(),b=geometry.number();long nx=(long)x+((a>>>1)^-(a&1)),ny=(long)y+((b>>>1)^-(b&1));if(Math.abs(nx)>10000000||Math.abs(ny)>10000000||++tile.vertices>400000)throw new IOException(Messages.text("geometry_too_complex"));x=(int)nx;y=(int)ny;if(command==1){if(part!=null)save(f,part);part=new ArrayList<>();}if(part==null)throw new IOException(Messages.text("missing_line_start"));part.add((float)x);part.add((float)y);}}if(part!=null)save(f,part);f.path.setFillType(Path.FillType.EVEN_ODD);boolean first=true;for(float[] points:f.parts){for(int i=0;i<points.length;i+=2){float px=points[i],py=points[i+1];if(first){f.bounds.set(px,py,px,py);first=false;}else{f.bounds.left=Math.min(f.bounds.left,px);f.bounds.right=Math.max(f.bounds.right,px);f.bounds.top=Math.min(f.bounds.top,py);f.bounds.bottom=Math.max(f.bounds.bottom,py);}if(i==0)f.path.moveTo(px,py);else f.path.lineTo(px,py);}if(f.type==3)f.path.close();}return f;}
 static void save(Feature f,ArrayList<Float> part){float[] points=new float[part.size()];for(int i=0;i<points.length;i++)points[i]=part.get(i);f.parts.add(points);}
}
